"""TY Toda-Yamamoto Full Seed Audit
Runs TY on all 4 seeds × 6 pairs with both 11-point and 10-point data.
Implements two TY variants:
  A) method_ablation style (hand OLS, F-test, ADF for d_max, p=1 fixed)
  B) statsmodels VAR test_causality (Wald chi2, d=1 hardcoded, AIC for p)
"""

import json, warnings
import numpy as np
import pandas as pd
from scipy import stats
from statsmodels.tsa.api import VAR
from statsmodels.tsa.stattools import adfuller

warnings.filterwarnings('ignore')

SEEDS = [42, 43, 44, 45]
BASE = "/root/autodl-tmp/distrib_canary_collapse/results/mvp"
PAIRS = [
    ("token_entropy", "distinct_1", "TE→d1"),
    ("token_entropy", "distinct_2", "TE→d2"),
    ("token_entropy", "distinct_3", "TE→d3"),
    ("ece", "distinct_1", "ECE→d1"),
    ("ece", "distinct_2", "ECE→d2"),
    ("ece", "distinct_3", "ECE→d3"),
]
ALPHA = 0.05

# --- Load data ---
all_data = {}
for s in SEEDS:
    with open(f"{BASE}/rep_{s}/all_metrics.json") as f:
        raw = json.load(f)
    all_data[s] = sorted(raw, key=lambda x: x["generation"])

print(f"Seeds: {SEEDS}")
for s in SEEDS:
    gens = [m['generation'] for m in all_data[s]]
    print(f"  seed {s}: {len(all_data[s])} points, generations {gens}")

# --- ADF integration order ---
def adf_order(series, max_d=2):
    for d in range(max_d + 1):
        s = series.copy()
        for _ in range(d):
            s = np.diff(s)
        if len(s) < 5:
            return d
        try:
            if adfuller(s, maxlag=1, autolag=None)[1] < 0.05:
                return d
        except:
            pass
    return max_d

# --- TY Method A: method_ablation style (hand OLS, F-test) ---
def ty_method_a(x, y):
    n = len(x)
    dc, dd = adf_order(x), adf_order(y)
    d_max = max(dc, dd)
    p = 1
    k = p + d_max
    T_eff = n - k
    n_params = 1 + 2 * k
    df_resid = T_eff - n_params

    if df_resid < 1:
        return {"F": None, "p": None, "sig": False, "d_max": d_max, "p_lag": p, "k": k,
                "df_resid": df_resid, "dc": dc, "dd": dd, "note": f"no df (T_eff={T_eff}, params={n_params})"}

    Y = y[k:]
    X_cols = [np.ones(T_eff)]
    for l in range(1, k + 1):
        X_cols.append(x[k - l : n - l])
        X_cols.append(y[k - l : n - l])
    X = np.column_stack(X_cols)

    try:
        beta = np.linalg.lstsq(X, Y, rcond=None)[0]
        resid = Y - X @ beta
        sigma2 = np.sum(resid ** 2) / df_resid
        XtX_inv = np.linalg.inv(X.T @ X)
    except:
        return {"F": None, "p": None, "sig": False, "d_max": d_max, "p_lag": p, "k": k,
                "df_resid": df_resid, "dc": dc, "dd": dd, "note": "OLS failed"}

    test_idx = [2 * (l - 1) + 1 for l in range(1, p + 1)]
    R = np.zeros((p, n_params))
    for i, idx in enumerate(test_idx):
        R[i, idx] = 1.0

    Rb = R @ beta
    try:
        cov_Rb = sigma2 * (R @ XtX_inv @ R.T)
        W = float(Rb @ np.linalg.inv(cov_Rb) @ Rb)
        F = W / p
        pval = float(1.0 - stats.f.cdf(F, p, df_resid))
    except:
        return {"F": None, "p": None, "sig": False, "d_max": d_max, "p_lag": p, "k": k,
                "df_resid": df_resid, "dc": dc, "dd": dd, "note": "Wald failed"}

    return {"F": round(F, 4), "p": round(pval, 6), "sig": pval < ALPHA,
            "d_max": d_max, "p_lag": p, "k": k, "df_resid": df_resid, "dc": dc, "dd": dd, "note": ""}

# --- TY Method B: statsmodels VAR (Wald chi2, AIC lag, d=1 fixed) ---
def ty_method_b(x, y, maxlag=2):
    data = pd.DataFrame({'cause': x, 'effect': y})
    n = len(x)
    d = 1
    best_p = 1
    best_aic = np.inf
    for p_try in range(1, min(maxlag + 1, max(2, n // 3))):
        try:
            model = VAR(data)
            result = model.fit(p_try)
            if result.aic < best_aic:
                best_aic = result.aic
                best_p = p_try
        except:
            continue
    p_d = best_p + d
    if p_d >= n - 2:
        return {"chi2": None, "p": None, "sig": False, "p_lag": best_p, "d": d, "note": "not enough obs"}
    try:
        model = VAR(data)
        result = model.fit(p_d)
        test_result = result.test_causality('effect', ['cause'], kind='wald')
        pval = float(test_result.pvalue)
        chi2_val = float(test_result.test_statistic)
        return {"chi2": round(chi2_val, 4), "p": round(pval, 6), "sig": pval < ALPHA,
                "p_lag": best_p, "d": d, "note": ""}
    except Exception as e:
        return {"chi2": None, "p": None, "sig": False, "p_lag": best_p, "d": d, "note": str(e)[:50]}

# --- Run both methods for both 11-point and 10-point data ---
results = {}
for n_points, label in [(11, "11pt"), (10, "10pt")]:
    results[label] = {}
    for seed in SEEDS:
        results[label][seed] = {}
        metrics = all_data[seed][:n_points]
        for x_key, y_key, pair_name in PAIRS:
            x = np.array([m[x_key] for m in metrics])
            y = np.array([m[y_key] for m in metrics])

            res_a = ty_method_a(x, y)
            res_b = ty_method_b(x, y)
            results[label][seed][pair_name] = {"method_a": res_a, "method_b": res_b}

# --- Print results ---
print("\n" + "="*100)
print("TODA-YAMAMOTO AUDIT: 11-point (gen_0-gen_10) vs 10-point (gen_0-gen_9)")
print("="*100)

for label in ["11pt", "10pt"]:
    print(f"\n{'─'*100}")
    print(f"  {label.upper()} DATA")
    print(f"{'─'*100}")

    # Method A table
    print(f"\n  Method A (hand OLS, F-test, ADF d_max, p=1 fixed):")
    print(f"  {'Pair':<10} {'s42':>20} {'s43':>20} {'s44':>20} {'s45':>20}")
    print(f"  {'':10} {'F / p-val':>20} {'F / p-val':>20} {'F / p-val':>20} {'F / p-val':>20}")
    for _, _, pn in PAIRS:
        cells = [f"  {pn:<10}"]
        for seed in SEEDS:
            r = results[label][seed][pn]["method_a"]
            if r["F"] is not None:
                sig_mark = "*" if r["sig"] else " "
                cells.append(f"{r['F']:6.2f} / {r['p']:.4f}{sig_mark}")
            else:
                cells.append(f"{'N/A':>20}")
        print(" ".join(cells))

    # Method A detail
    print(f"\n  Method A details (d_max, k, df_resid):")
    for _, _, pn in PAIRS:
        for seed in SEEDS:
            r = results[label][seed][pn]["method_a"]
            print(f"    {pn} s{seed}: dc={r['dc']}, dd={r['dd']}, d_max={r['d_max']}, k={r['k']}, df_resid={r['df_resid']} {r['note']}")

    # Method B table
    print(f"\n  Method B (statsmodels VAR, Wald chi2, d=1, AIC lag):")
    print(f"  {'Pair':<10} {'s42':>20} {'s43':>20} {'s44':>20} {'s45':>20}")
    print(f"  {'':10} {'chi2 / p-val':>20} {'chi2 / p-val':>20} {'chi2 / p-val':>20} {'chi2 / p-val':>20}")
    for _, _, pn in PAIRS:
        cells = [f"  {pn:<10}"]
        for seed in SEEDS:
            r = results[label][seed][pn]["method_b"]
            if r["chi2"] is not None:
                sig_mark = "*" if r["sig"] else " "
                cells.append(f"{r['chi2']:6.2f} / {r['p']:.4f}{sig_mark}")
            else:
                cells.append(f"{'N/A':>20}")
        print(" ".join(cells))

# --- Significance summary ---
print(f"\n{'='*100}")
print("SIGNIFICANCE SUMMARY (p < 0.05)")
print(f"{'='*100}")
print(f"\n  {'Pair':<10} {'Method':<12} {'11pt sig_seeds':>16} {'10pt sig_seeds':>16} {'FLIP?':>8}")
for _, _, pn in PAIRS:
    for method_key, method_name in [("method_a", "OLS-F"), ("method_b", "VAR-chi2")]:
        sig_11 = sum(1 for s in SEEDS if results["11pt"][s][pn][method_key]["sig"])
        sig_10 = sum(1 for s in SEEDS if results["10pt"][s][pn][method_key]["sig"])
        flip = "YES" if sig_11 != sig_10 else ""
        print(f"  {pn:<10} {method_name:<12} {sig_11:>10}/4       {sig_10:>10}/4       {flip:>8}")

# --- FNR calculation ---
print(f"\n{'='*100}")
print("FNR CALCULATION (using Method A = method_ablation implementation, 11pt)")
print(f"{'='*100}")
print("\nPer-pair sig_seeds count (p < 0.05):")
fnr_miss = 0
fnr_total = len(PAIRS)
for _, _, pn in PAIRS:
    sig_count = sum(1 for s in SEEDS if results["11pt"][s][pn]["method_a"]["sig"])
    status = "DETECTED (≥3)" if sig_count >= 3 else "MISSED (<3)"
    if sig_count < 3:
        fnr_miss += 1
    print(f"  {pn:<10}: {sig_count}/4 sig seeds → {status}")

fnr = fnr_miss / fnr_total
print(f"\nFNR = {fnr_miss}/{fnr_total} = {fnr:.1%}")
print(f"(Paper claims FNR=33.3% = 2/6)")

# --- Save JSON ---
output = {"results": {}, "summary": {}}
for label in ["11pt", "10pt"]:
    output["results"][label] = {}
    for seed in SEEDS:
        output["results"][label][str(seed)] = {}
        for _, _, pn in PAIRS:
            output["results"][label][str(seed)][pn] = results[label][seed][pn]

with open("/root/autodl-tmp/distrib_canary_collapse/ty_audit_results.json", "w") as f:
    json.dump(output, f, indent=2, default=str)
print("\nResults saved to ty_audit_results.json")
PYEOF
echo "Script written"

